        return CGAL::ON_UNBOUNDED_SIDE;
    }

    // Check if the point is on the boundary
    for (std::size_t i = 0; i < polygon.size(); ++i) {
        const Point_2& p1 = polygon[i];
        const Point_2& p2 = polygon[(i + 1) % polygon.size()];

        // Check if the point is on the current edge
        CGAL::Oriented_side os = CGAL::orientation(p1, p2, point);
        if (os == CGAL::COLLINEAR) {
            // Check if the point is between p1 and p2
            if ((point.x() - p1.x()) * (point.x() - p2.x()) <= 0 &&
                (point.y() - p1.y()) * (point.y() - p2.y()) <= 0) {
                return CGAL::ON_BOUNDARY;
            }
        }
    }

    // Ray casting algorithm
    int count = 0;
    std::size_t n = polygon.size();
    for (std::size_t i = 0, j = n - 1; i < n; j = i++) {
        const Point_2& pi = polygon[i];
        const Point_2& pj = polygon[j];

        // Check if the point is between the y-coordinates of the edge
        if (((pi.y() > point.y()) != (pj.y() > point.y())) {
            // Compute the x-coordinate of the intersection
            double x_intersect = (pj.x() - pi.x()) * (point.y() - pi.y()) / (pj.y() - pi.y()) + pi.x();

            // Check if the point is to the left of the intersection
            if (point.x() < x_intersect) {
                ++count;
            } else if (point.x() == x_intersect) {
                return CGAL::ON_BOUNDARY;
            }
        }
    }

    return (count % 2 == 1) ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;
    // END_CODE

